import{_ as i,o as s,c as n,a3 as a}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"Authentifizierung","description":"API-Schlüssel und Bearer-Token, Rollen und was bei fehlenden Rechten passiert.","frontmatter":{"title":"Authentifizierung","description":"API-Schlüssel und Bearer-Token, Rollen und was bei fehlenden Rechten passiert."},"headers":[],"relativePath":"api/authentifizierung.md","filePath":"api/authentifizierung.md","lastUpdated":1788104932000}'),t={name:"api/authentifizierung.md"};function l(h,e,d,r,p,o){return s(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="authentifizierung" tabindex="-1">Authentifizierung <a class="header-anchor" href="#authentifizierung" aria-label="Permalink to &quot;Authentifizierung&quot;">​</a></h1><p>Jede Anfrage an <code>/api</code> trägt ihre Identität im Header <code>Authorization</code>. Das Backend kennt zwei Verfahren.</p><h2 id="api-schlussel-empfohlen-fur-integrationen" tabindex="-1">API-Schlüssel (empfohlen für Integrationen) <a class="header-anchor" href="#api-schlussel-empfohlen-fur-integrationen" aria-label="Permalink to &quot;API-Schlüssel (empfohlen für Integrationen)&quot;">​</a></h2><p>Ein API-Schlüssel besteht aus <strong>Schlüssel</strong> und <strong>Geheimnis</strong> und wird als HTTP-Basic-Anmeldung gesendet: Schlüssel als Benutzername, Geheimnis als Passwort.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APPTIVE_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APPTIVE_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://app.apptivegrid.de/api/users/me</span></span></code></pre></div><p>Ausgeschrieben ist das der Header</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Basic base64(schlüssel:geheimnis)</span></span></code></pre></div><h3 id="schlussel-erzeugen" tabindex="-1">Schlüssel erzeugen <a class="header-anchor" href="#schlussel-erzeugen" aria-label="Permalink to &quot;Schlüssel erzeugen&quot;">​</a></h3><p>In der Anwendung unter <strong>Profil &amp; Einstellungen → API Zugangsdaten</strong> (<code>https://app.apptivegrid.de/settings/credentials</code>). Zur Auswahl stehen zwei Rollen:</p><table tabindex="0"><thead><tr><th>Auswahl in der Oberfläche</th><th>Rolle in der API</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Admin</strong></td><td><code>admin</code></td><td>Voller Zugriff auf alle Spaces des Kontos</td></tr><tr><td><strong>Nur lesen</strong></td><td><code>reader</code></td><td>Lesezugriff auf alle Spaces des Kontos</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Das Geheimnis wird genau einmal angezeigt</p><p>Nach dem Schließen des Dialogs lässt es sich nicht wieder abrufen. Ist es verloren, löschen Sie den Schlüssel und erzeugen einen neuen.</p></div><p>Derselbe Vorgang über die API — er setzt eine bestehende Anmeldung voraus:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;Buchhaltungs-Import&quot;, &quot;role&quot;: &quot;reader&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://app.apptivegrid.de/api/users/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/accessKeys</span></span></code></pre></div><p>Antwort:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;secret&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Buchhaltungs-Import&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>role</code> akzeptiert ausschließlich <code>reader</code> oder <code>admin</code>; jeder andere Wert ergibt <code>400</code>.</p><p>Vorhandene Schlüssel auflisten und löschen:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APPTIVE_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APPTIVE_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://app.apptivegrid.de/api/users/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/accessKeys</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APPTIVE_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APPTIVE_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://app.apptivegrid.de/api/users/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/accessKeys/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KEY_ID</span></span></code></pre></div><p>Das Geheimnis erscheint in der Liste nicht.</p><h2 id="bearer-token" tabindex="-1">Bearer-Token <a class="header-anchor" href="#bearer-token" aria-label="Permalink to &quot;Bearer-Token&quot;">​</a></h2><p>Das Zugriffstoken aus der Anmeldung der Weboberfläche wird als JWT geschickt:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;token&gt;</span></span></code></pre></div><p>Das ist das Verfahren des Frontends. Für Server-zu-Server-Integrationen ist der API-Schlüssel der einfachere Weg, weil er nicht abläuft.</p><div class="warning custom-block"><p class="custom-block-title">Ohne <code>Authorization</code> gibt es fast nichts zu sehen</p><p>Fehlt der Header, behandelt das Backend die Anfrage als nicht autorisiert; alles unterhalb von <code>/api/users</code> antwortet dann mit <code>401</code>.</p><p>Drei Ausnahmen sind bewusst offen:</p><ul><li>die <a href="#öffentliche-links-ohne-anmeldung">öffentlichen Links</a> unter <code>/api/a/…</code> und <code>/api/r/…</code>,</li><li>die Metadaten-Endpunkte <code>GET /api/types</code>, <code>/api/nodeTypes</code>, <code>/api/blocks</code> und <code>/api/version</code>,</li><li><code>GET /api/users/me</code>, das ohne Zugangsdaten allerdings <code>401</code> liefert, weil es die Identität ja gerade auflösen soll.</li></ul></div><h2 id="die-eigene-benutzerkennung-finden" tabindex="-1">Die eigene Benutzerkennung finden <a class="header-anchor" href="#die-eigene-benutzerkennung-finden" aria-label="Permalink to &quot;Die eigene Benutzerkennung finden&quot;">​</a></h2><p>Fast alle Pfade beginnen mit <code>/api/users/{userId}</code>. Die eigene Kennung liefert eine Weiterleitung:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APPTIVE_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APPTIVE_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://app.apptivegrid.de/api/users/me</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 302 Found</span></span>
<span class="line"><span>Location: /api/users/64f1a2b3c4d5e6f708091a2b</span></span></code></pre></div><p>Der Kennung folgen — <code>curl -L</code> — liefert die Benutzerressource mit allen weiterführenden <code>_links</code>.</p><h2 id="rollen-und-berechtigungen" tabindex="-1">Rollen und Berechtigungen <a class="header-anchor" href="#rollen-und-berechtigungen" aria-label="Permalink to &quot;Rollen und Berechtigungen&quot;">​</a></h2><p>Jede Operation ist im Backend an eine benannte Berechtigung gebunden, und jede Berechtigung nennt die Rollen, die sie ausüben dürfen. Es gibt vier Rollen:</p><table tabindex="0"><thead><tr><th>Rolle</th><th>Darf</th></tr></thead><tbody><tr><td><code>reader</code></td><td>Lesen</td></tr><tr><td><code>writer</code></td><td>Lesen und Daten ändern</td></tr><tr><td><code>admin</code></td><td>Alles, einschließlich Struktur ändern und freigeben</td></tr><tr><td><code>creator</code></td><td>Nur anlegen — kommt bei <code>addEntity</code> vor und erlaubt das Einreichen von Einträgen ohne Leserecht</td></tr></tbody></table><p>Welche Rolle für einen konkreten Endpunkt reicht, steht bei jedem Endpunkt in der <a href="/openapi.json">OpenAPI-Beschreibung</a> unter <code>x-apptivegrid-roles</code> sowie in der <a href="/api/referenz">Endpunkt-Referenz</a>.</p><p>Ein paar Regelmäßigkeiten, die das Bild ordnen:</p><ul><li>Struktur ändern — Space, Grid, Feld, Ansicht anlegen oder löschen, freigeben — verlangt durchgehend <code>admin</code>.</li><li>Einträge lesen genügt <code>reader</code>, Einträge ändern verlangt <code>writer</code>.</li><li>Wer keine Rolle auf der Ressource hat, bekommt <code>403</code>, nicht <code>404</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Rechte stehen in der Antwort</p><p>Statt Rollen nachzubilden, prüfen Sie <code>_links</code> der Ressource: nur erlaubte Operationen erscheinen dort. → <a href="/api/uebersicht#die-api-ist-selbstbeschreibend">Überblick</a></p></div><h2 id="woher-eine-identitat-ihre-rollen-bekommt" tabindex="-1">Woher eine Identität ihre Rollen bekommt <a class="header-anchor" href="#woher-eine-identitat-ihre-rollen-bekommt" aria-label="Permalink to &quot;Woher eine Identität ihre Rollen bekommt&quot;">​</a></h2><ul><li>Der Kontoinhaber ist Administrator seiner eigenen Spaces.</li><li>Eine <strong>Space-Freigabe</strong> (<code>POST …/spaces/{spaceId}/shares</code> mit <code>email</code> und <code>role</code>) gibt einer anderen Person eine Rolle in diesem Space.</li><li>Ein <strong>API-Schlüssel</strong> trägt die Rolle, die bei seiner Erzeugung gewählt wurde, und wirkt auf alle Spaces des Kontos.</li><li>Ein <strong>öffentlicher Link</strong> kann eine Rolle mitbringen, ohne dass sich jemand anmeldet.</li></ul><h2 id="offentliche-links-ohne-anmeldung" tabindex="-1">Öffentliche Links ohne Anmeldung <a class="header-anchor" href="#offentliche-links-ohne-anmeldung" aria-label="Permalink to &quot;Öffentliche Links ohne Anmeldung&quot;">​</a></h2><p>Formulare, geteilte Ansichten und Bearbeitungslinks liegen unter <code>/api/a/…</code> und <code>/api/r/…</code> und sind bewusst ohne Konto erreichbar. Ein Link kann zusätzlich geschützt sein:</p><table tabindex="0"><thead><tr><th>Antwort</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>401</code> mit <code>Apptive-Authorization: link</code></td><td>Der Link verlangt Benutzername und Passwort. Diese als HTTP-Basic senden.</td></tr><tr><td><code>401</code> mit <code>Apptive-Authorization: internal</code></td><td>Der Link verlangt eine angemeldete ApptiveGrid-Identität.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ein mit Passwort geschützter Ansichtslink</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;linkbenutzer:linkpasswort&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://app.apptivegrid.de/api/a/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$LINK_ID</span></span></code></pre></div><p>Der Header <code>Apptive-Authorization</code> erscheint nur bei <code>401</code> und sagt, welche Art von Anmeldung erwartet wird.</p>`,43)])])}const u=i(t,[["render",l]]);export{c as __pageData,u as default};
